  "scene sets: one open set, an empty set is free, a discard and a cancel with their refusals": [
    "# the avatar already has an open set: a second compose, even an empty one, is refused",
    "> scenes.compose {\"avatarId\":\"avatar#1\",\"count\":0,\"categories\":[],\"poses\":{\"profile\":false,\"back\":false},\"acceptedWorstMicros\":0}",
    "< error VALIDATION {\"sceneReason\":\"open-set\"}",
    "# an unknown set is NOT_FOUND for every command that names one; a cancel of a set that does not run is ok",
    "> scenes.edit {\"sceneSetId\":\"set#1\",\"revision\":1,\"op\":{\"op\":\"remove\",\"sceneIds\":[1]}}",
    "< error NOT_FOUND {\"detail\":\"no scene set set#1 in the open library\"}",
    "> scenes.cancel {\"sceneSetId\":\"set#1\"}",
    "< error NOT_FOUND {\"detail\":\"no scene set set#1 in the open library\"}",
    "> scenes.discard {\"sceneSetId\":\"set#1\"}",
    "< error NOT_FOUND {\"detail\":\"no scene set set#1 in the open library\"}",
    "> scenes.cancel {\"sceneSetId\":\"set#2\"}",
    "< ok {\"sceneSetId\":\"set#2\"}",
    "# a discard frees the avatar: an empty set is then free, and is the one the avatar has",
    "> scenes.discard {\"sceneSetId\":\"set#2\"}",
    "< ok {\"sceneSetId\":\"set#2\"}",
    "> scenes.get {\"avatarId\":\"avatar#1\"}",
    "< ok {\"sceneSet\":null,\"unreadable\":1}",
    "> scenes.compose {\"avatarId\":\"avatar#1\",\"count\":0,\"categories\":[],\"poses\":{\"profile\":false,\"back\":false},\"acceptedWorstMicros\":0}",
    "< ok {\"sceneSetId\":\"set#3\",\"jobId\":null}",
    "> scenes.get {\"avatarId\":\"avatar#1\"}",
    "< ok {\"sceneSet\":{\"sceneSetId\":\"set#3\",\"avatarId\":\"avatar#1\",\"createdAt\":\"<masked>\",\"revision\":1,\"status\":\"ready\",\"stoppedBy\":null,\"stoppedError\":null,\"runId\":null,\"poses\":{\"profile\":false,\"back\":false},\"categories\":[],\"textModel\":\"x-ai/grok-4.3\",\"spentMicros\":0,\"openReserveMicros\":0,\"write\":null,\"lastCompose\":null,\"chunks\":[],\"scenes\":[]},\"unreadable\":1}",
  ],
