  "photos list pages by cursor: a position, a gone photo, the last one, a forged value": [
    "> photos.list {\"avatarId\":\"avatar#1\"}",
    "< ok photos {\"count\":22,\"free\":22,\"skippedTotal\":0,\"order\":\"22..1\"}",
    "# from the tenth photo of the list: the ones older than it, in order",
    "> photos.list {\"avatarId\":\"avatar#1\",\"cursor\":\"<masked>|photo#13\"}",
    "< ok photos {\"count\":12,\"free\":12,\"skippedTotal\":0,\"order\":\"12..1\"}",
    "# from a photo that is not in the library, at the time of the fifth (its id sorts before every real one, so a tie at that time is never taken in): the same position rule, nothing to find",
    "> photos.list {\"avatarId\":\"avatar#1\",\"cursor\":\"<masked>|photo#25\"}",
    "< ok photos {\"count\":17,\"free\":17,\"skippedTotal\":0,\"order\":\"17..1\"}",
    "# from the oldest photo: an empty last page",
    "> photos.list {\"avatarId\":\"avatar#1\",\"cursor\":\"<masked>|photo#1\"}",
    "< ok photos {\"count\":0,\"free\":0,\"skippedTotal\":0,\"order\":\"\"}",
    "# a value that is not a cursor is refused, and the list still answers",
    "> photos.list {\"avatarId\":\"avatar#1\",\"cursor\":\"forged\"}",
    "< error VALIDATION {}",
    "> photos.list {\"avatarId\":\"avatar#1\"}",
    "< ok photos {\"count\":22,\"free\":22,\"skippedTotal\":0,\"order\":\"22..1\"}",
  ],
